# Check the middle column structure
# Grid is 19x19, middle column is 9

for c in range(19):
    col_symbol = set(grid[r][c] for r in range(19))
    if col_symbol == {'.'} or len(col_symbol) == 1:
        print(f"Col {c}: {grid[0][c]} (uniform)")
    else:
        print(f"Col {c}: {col_symbol}")

# Compare left half vs right half dominance
left_count = [row[:10].count('A') - row[:10].count('B') for row in grid]
right_count = [row[10:].count('A') - row[10:].count('B') for row in grid]

print("Left-half (A-B) dominance:", left_count)
print("Right-half (A-B) dominance:", right_count)

# Check if they're opposites or related
for i, (l, r) in enumerate(zip(left_count, right_count)):
    if l > 0 and r < 0:
        print(f"Row {i}: left favors A ({l}), right favors B ({r})")
    elif l < 0 and r > 0:
        print(f"Row {i}: left favors B ({l}), right favors A ({r})")
    elif l == 0 and r == 0:
        print(f"Row {i}: neutral both sides")
    elif l > 0 and r > 0:
        print(f"Row {i}: A favored both")
    elif l < 0 and r < 0:
        print(f"Row {i}: B favored both")
